param([ValidateSet('start','abort')][string]$Action,[string]$MissionFile='');$ErrorActionPreference='Stop';$root=(Resolve-Path "$PSScriptRoot/../..").Path;$runtime=Join-Path $PSScriptRoot '.runtime';$launch=Join-Path $runtime 'mission-control-launch.json';function Write-Atomic([string]$Path,[object]$Value){$temporary="$Path.tmp";$Value|ConvertTo-Json -Compress|Set-Content -LiteralPath $temporary -NoNewline;Move-Item -LiteralPath $temporary -Destination $Path -Force};function Active-Launch{if(!(Test-Path -LiteralPath $launch)){return $null};try{$value=Get-Content -LiteralPath $launch -Raw|ConvertFrom-Json;if(Get-Process -Id $value.pid -ErrorAction SilentlyContinue){return $value}}catch{};return $null};if($Action -eq 'start'){if(Active-Launch){exit 0};$runner=Join-Path $PSScriptRoot 'Run.ps1';$process=Start-Process -FilePath powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$runner,'-Mode','slice','-MissionFile',('"'+$MissionFile+'"')) -WindowStyle Hidden -PassThru;Write-Atomic $launch @{pid=$process.Id;startedUtc=[DateTime]::UtcNow.ToString('o');mode='slice'};exit 0};$active=Get-ChildItem -LiteralPath $runtime -Directory -Filter 'slice-*'|Where-Object{(Test-Path (Join-Path $_.FullName 'session.json')) -and !(Test-Path (Join-Path $_.FullName 'summary.json'))}|Sort-Object LastWriteTime -Descending|Select-Object -First 1;if($null -ne $active){Write-Atomic (Join-Path $active.FullName 'abort.request') @{requestedUtc=[DateTime]::UtcNow.ToString('o');source='Unity Mission Control'}}
